```yaml
name: Auto-approve Copilot Workflows
on:
  workflow_run:
    workflows: ["Copilot Setup Steps"]
    types:
      - completed

permissions:
  contents: read
  pull-requests: write

jobs:
  auto-approve:
    if: github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd # v6

      - name: Approve and comment PR
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.workflow_run.pull_requests[0].number
            });

            // Check if the PR is from a fork
            if (pr.head.repo.full_name !== pr.base.repo.full_name) {
              console.log("PR is from a fork, skipping approval");
              return;
            }

            // Check if the PR has the required label
            const hasLabel = pr.labels.some(label => label.name === 'auto-approve');
            if (!hasLabel) {
              console.log("PR does not have 'auto-approve' label, skipping approval");
              return;
            }

            // Approve the PR
            await github.rest.pulls.createReview({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.workflow_run.pull_requests[0].number,
              event: 'APPROVE',
              body: 'Auto-approved by Copilot workflow'
            });

            // Comment on the PR
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.workflow_run.pull_requests[0].number,
              body: 'This PR was auto-approved by the Copilot workflow.'
            });
```

